import { useRef, useEffect, useState } from 'react';
import { useProjectStore } from '@/stores/useProjectStore';
import { useUIStore } from '@/stores/useUIStore';
import { X, ZoomIn, ZoomOut, Image } from 'lucide-react';
import clsx from 'clsx';

export default function PreviewPanel() {
  const { currentProject } = useProjectStore();
  const { previewPanelOpen, togglePreviewPanel } = useUIStore();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [zoom, setZoom] = useState(1);

  // 渲染点阵图预览
  useEffect(() => {
    if (!currentProject || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const cellSize = Math.max(4, Math.floor(200 / Math.max(currentProject.width, currentProject.height)));
    const w = currentProject.width * cellSize;
    const h = currentProject.height * cellSize;

    canvas.width = w * zoom;
    canvas.height = h * zoom;

    ctx.imageSmoothingEnabled = false;

    for (let y = 0; y < currentProject.height; y++) {
      for (let x = 0; x < currentProject.width; x++) {
        const ci = currentProject.gridData[y]?.[x];
        if (ci >= 0 && ci < currentProject.palette.length) {
          ctx.fillStyle = currentProject.palette[ci].hex;
          ctx.fillRect(x * cellSize * zoom, y * cellSize * zoom, cellSize * zoom, cellSize * zoom);
        }
      }
    }
  }, [currentProject, zoom]);

  if (!previewPanelOpen || !currentProject) return null;

  return (
    <div className="w-64 bg-white border-l border-stone-200 flex flex-col shrink-0 overflow-hidden">
      {/* 标题栏 */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-stone-100">
        <div className="flex items-center gap-1.5">
          <Image className="w-4 h-4 text-stone-400" />
          <span className="text-xs font-medium text-stone-600">预览</span>
        </div>
        <button
          onClick={togglePreviewPanel}
          className="p-1 rounded-md text-stone-400 hover:text-stone-600 hover:bg-stone-100 transition-colors"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      <div className="flex-1 overflow-auto p-3 space-y-4">
        {/* 原图 */}
        {currentProject.originalImage && (
          <div>
            <p className="text-[10px] text-stone-400 font-medium mb-1.5">原图</p>
            <div className="rounded-lg overflow-hidden border border-stone-200 bg-stone-50">
              <img
                src={currentProject.originalImage}
                alt="原图"
                className="w-full object-contain"
                style={{ maxHeight: 180 }}
              />
            </div>
          </div>
        )}

        {/* 点阵图预览 */}
        <div>
          <p className="text-[10px] text-stone-400 font-medium mb-1.5">
            点阵图 ({currentProject.width}×{currentProject.height})
          </p>
          <div className="rounded-lg overflow-hidden border border-stone-200 bg-stone-50 flex items-center justify-center p-1">
            <canvas
              ref={canvasRef}
              className="max-w-full max-h-64"
            />
          </div>
        </div>
      </div>

      {/* 缩放控制 */}
      <div className="flex items-center justify-center gap-2 px-3 py-2 border-t border-stone-100">
        <button
          onClick={() => setZoom((z) => Math.max(0.5, z - 0.25))}
          className="p-1 rounded-md text-stone-400 hover:text-stone-600 hover:bg-stone-100 transition-colors"
        >
          <ZoomOut className="w-3.5 h-3.5" />
        </button>
        <span className="text-xs text-stone-500 tabular-nums w-10 text-center">
          {Math.round(zoom * 100)}%
        </span>
        <button
          onClick={() => setZoom((z) => Math.min(4, z + 0.25))}
          className="p-1 rounded-md text-stone-400 hover:text-stone-600 hover:bg-stone-100 transition-colors"
        >
          <ZoomIn className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  );
}