import { useProjectStore } from '@/stores/useProjectStore';
import { useEditorStore } from '@/stores/useEditorStore';
import { palettes } from '@/utils/palette';
import clsx from 'clsx';

export default function ColorPalette() {
  const { currentProject } = useProjectStore();
  const { brushColorIndex, setBrushColorIndex, setBrushColor, setActiveTool } =
    useEditorStore();

  if (!currentProject) return null;

  const palette = currentProject.palette;

  if (palette.length === 0) {
    return (
      <div className="flex items-center justify-center h-14 bg-white border-t border-stone-200 text-xs text-stone-400 shrink-0">
        暂无色板数据，请导入图片或手动添加颜色
      </div>
    );
  }

  const handleSelect = (index: number, hex: string) => {
    setBrushColorIndex(index);
    setBrushColor(hex);
    setActiveTool('brush');
  };

  // 按照色系分组展示
  let colorOffset = 0;
  const groups = palettes.map((group) => {
    const colors = group.colors.map((c, i) => {
      const globalIndex = colorOffset + i;
      return { ...c, globalIndex, projectColor: palette[globalIndex] };
    });
    colorOffset += group.colors.length;
    return { name: group.name, colors };
  });

  return (
    <div className="bg-white h-full overflow-y-auto">
      <div className="px-3 py-2 space-y-2">
        {groups.map((group) => (
          <div key={group.name}>
            <div className="text-[10px] font-semibold text-stone-400 mb-1 uppercase tracking-wider">
              {group.name}
            </div>
            <div className="flex items-center gap-1 flex-wrap">
              {group.colors.map((color) => {
                const isSelected = brushColorIndex === color.globalIndex;
                return (
                  <button
                    key={color.globalIndex}
                    onClick={() => handleSelect(color.globalIndex, color.hex)}
                    title={`${color.name}${color.projectColor ? ` (${color.projectColor.count} 颗)` : ''}`}
                    className={clsx(
                      'w-6 h-6 rounded-md shadow-sm border transition-all duration-150',
                      isSelected
                        ? 'ring-2 ring-brand-500 ring-offset-1 scale-110'
                        : 'hover:scale-110 hover:z-10 hover:shadow-md border-stone-200'
                    )}
                    style={{ backgroundColor: color.hex }}
                  />
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}