// 图纸导出功能
import type { Project } from '../stores/useProjectStore';

// 导出为 PNG 图片
export function exportAsPNG(project: Project, cellSize: number = 16): void {
  const canvas = document.createElement('canvas');
  canvas.width = project.width * cellSize;
  canvas.height = project.height * cellSize;
  const ctx = canvas.getContext('2d')!;
  
  // 白色背景
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  
  // 绘制每个格子
  for (let y = 0; y < project.height; y++) {
    for (let x = 0; x < project.width; x++) {
      const ci = project.gridData[y]?.[x];
      if (ci >= 0 && ci < project.palette.length) {
        ctx.fillStyle = project.palette[ci].hex;
        ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
      }
    }
  }
  
  // 网格线
  if (project.settings.showGrid) {
    ctx.strokeStyle = 'rgba(0,0,0,0.08)';
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= project.width; x++) {
      ctx.beginPath();
      ctx.moveTo(x * cellSize, 0);
      ctx.lineTo(x * cellSize, canvas.height);
      ctx.stroke();
    }
    for (let y = 0; y <= project.height; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * cellSize);
      ctx.lineTo(canvas.width, y * cellSize);
      ctx.stroke();
    }
  }
  
  downloadCanvas(canvas, `${project.name}.png`);
}

// 导出为 JPG 图片
export function exportAsJPG(project: Project, cellSize: number = 16): void {
  const canvas = document.createElement('canvas');
  canvas.width = project.width * cellSize;
  canvas.height = project.height * cellSize;
  const ctx = canvas.getContext('2d')!;
  
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  
  for (let y = 0; y < project.height; y++) {
    for (let x = 0; x < project.width; x++) {
      const ci = project.gridData[y]?.[x];
      if (ci >= 0 && ci < project.palette.length) {
        ctx.fillStyle = project.palette[ci].hex;
        ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
      }
    }
  }
  
  downloadCanvas(canvas, `${project.name}.jpg`, 0.92);
}

// 导出为 A4/A5 打印排版
export function exportForPrint(
  project: Project,
  paperSize: 'A4' | 'A5' = 'A4'
): void {
  // A4 = 2480 x 3508 px at 300dpi, A5 = 1748 x 2480 px
  const paperWidth = paperSize === 'A4' ? 2480 : 1748;
  const paperHeight = paperSize === 'A4' ? 3508 : 2480;
  
  const canvas = document.createElement('canvas');
  canvas.width = paperWidth;
  canvas.height = paperHeight;
  const ctx = canvas.getContext('2d')!;
  
  // 白色纸张
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, paperWidth, paperHeight);
  
  // 计算最大可用区域 (留边距)
  const margin = 80;
  const maxW = paperWidth - margin * 2;
  const maxH = paperHeight - margin * 2;
  
  // 计算格子大小
  const cellW = Math.floor(maxW / project.width);
  const cellH = Math.floor(maxH / project.height);
  const cellSize = Math.min(cellW, cellH);
  
  const gridW = project.width * cellSize;
  const gridH = project.height * cellSize;
  const offsetX = Math.floor((paperWidth - gridW) / 2);
  const offsetY = Math.floor((paperHeight - gridH) / 2);
  
  // 绘制网格
  for (let y = 0; y < project.height; y++) {
    for (let x = 0; x < project.width; x++) {
      const ci = project.gridData[y]?.[x];
      if (ci >= 0 && ci < project.palette.length) {
        ctx.fillStyle = project.palette[ci].hex;
        ctx.fillRect(
          offsetX + x * cellSize,
          offsetY + y * cellSize,
          cellSize,
          cellSize
        );
      }
    }
  }
  
  // 网格线（打印辅助）
  ctx.strokeStyle = 'rgba(0,0,0,0.12)';
  ctx.lineWidth = 0.5;
  for (let x = 0; x <= project.width; x++) {
    ctx.beginPath();
    ctx.moveTo(offsetX + x * cellSize, offsetY);
    ctx.lineTo(offsetX + x * cellSize, offsetY + gridH);
    ctx.stroke();
  }
  for (let y = 0; y <= project.height; y++) {
    ctx.beginPath();
    ctx.moveTo(offsetX, offsetY + y * cellSize);
    ctx.lineTo(offsetX + gridW, offsetY + y * cellSize);
    ctx.stroke();
  }
  
  // 标题信息
  ctx.fillStyle = '#333';
  ctx.font = '24px "PingFang SC", sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(project.name, paperWidth / 2, margin / 2 + 12);
  
  // 色标
  const colorY = offsetY + gridH + 40;
  ctx.font = '14px "PingFang SC", sans-serif';
  ctx.textAlign = 'left';
  let cx = offsetX;
  for (const c of project.palette) {
    ctx.fillStyle = c.hex;
    ctx.fillRect(cx, colorY, 20, 20);
    ctx.strokeStyle = '#ccc';
    ctx.lineWidth = 1;
    ctx.strokeRect(cx, colorY, 20, 20);
    ctx.fillStyle = '#333';
    ctx.fillText(`${c.name} x${c.count}`, cx + 26, colorY + 15);
    cx += 100;
    if (cx > paperWidth - margin - 80) {
      cx = offsetX;
    }
  }
  
  downloadCanvas(canvas, `${project.name}_打印版_${paperSize}.png`);
}

// 保存工程文件 (JSON 导出)
export function saveProjectFile(project: Project): void {
  const json = JSON.stringify(project, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${project.name}.bead`;
  a.click();
  URL.revokeObjectURL(url);
}

// 加载工程文件
export function loadProjectFile(file: File): Promise<Project> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const project = JSON.parse(e.target?.result as string) as Project;
        resolve(project);
      } catch (err) {
        reject(new Error('无效的工程文件'));
      }
    };
    reader.onerror = reject;
    reader.readAsText(file);
  });
}

// 从 Canvas 下载
function downloadCanvas(
  canvas: HTMLCanvasElement,
  filename: string,
  quality?: number
): void {
  const mimeType = filename.endsWith('.jpg') ? 'image/jpeg' : 'image/png';
  const dataUrl = canvas.toDataURL(mimeType, quality);
  const a = document.createElement('a');
  a.href = dataUrl;
  a.download = filename;
  a.click();
}