import { create } from 'zustand';

export type ToolType = 'brush' | 'eraser' | 'fill' | 'eyedropper';

interface EditorStore {
  activeTool: ToolType;
  brushColorIndex: number;
  brushColor: string;
  isProcessing: boolean;
  filterType: 'none' | 'pixelate' | 'cartoon' | 'lineart';
  brightness: number;
  contrast: number;
  setActiveTool: (tool: ToolType) => void;
  setBrushColorIndex: (index: number) => void;
  setBrushColor: (color: string) => void;
  setIsProcessing: (v: boolean) => void;
  setFilterType: (f: EditorStore['filterType']) => void;
  setBrightness: (b: number) => void;
  setContrast: (c: number) => void;
}

export const useEditorStore = create<EditorStore>((set) => ({
  activeTool: 'brush',
  brushColorIndex: -1,
  brushColor: '#FF7A00',
  isProcessing: false,
  filterType: 'none',
  brightness: 0,
  contrast: 0,
  setActiveTool: (tool) => set({ activeTool: tool }),
  setBrushColorIndex: (index) => set({ brushColorIndex: index }),
  setBrushColor: (color) => set({ brushColor: color }),
  setIsProcessing: (v) => set({ isProcessing: v }),
  setFilterType: (f) => set({ filterType: f }),
  setBrightness: (b) => set({ brightness: b }),
  setContrast: (c) => set({ contrast: c }),
}));