// 获取所有颜色扁平列表
export function getAllColors(): { hex: string; name: string }[] {
  return palettes.flatMap((p) => p.colors);
}

// 根据 hex 查找颜色名称
export function findColorName(hex: string): string {
  const all = getAllColors();
  const upper = hex.toUpperCase();
  const found = all.find((c) => c.hex.toUpperCase() === upper);
  return found?.name || '未知';
}

// 欧几里得距离计算颜色相似度 (RGB)
export function colorDistanceRGB(c1: string, c2: string): number {
  const r1 = parseInt(c1.slice(1, 3), 16);
  const g1 = parseInt(c1.slice(3, 5), 16);
  const b1 = parseInt(c1.slice(5, 7), 16);
  const r2 = parseInt(c2.slice(1, 3), 16);
  const g2 = parseInt(c2.slice(3, 5), 16);
  const b2 = parseInt(c2.slice(5, 7), 16);
  return Math.sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2);
}

// RGB 转 XYZ
function rgbToXyz(r: number, g: number, b: number): { x: number; y: number; z: number } {
  r /= 255;
  g /= 255;
  b /= 255;

  r = r > 0.04045 ? Math.pow((r + 0.055) / 1.055, 2.4) : r / 12.92;
  g = g > 0.04045 ? Math.pow((g + 0.055) / 1.055, 2.4) : g / 12.92;
  b = b > 0.04045 ? Math.pow((b + 0.055) / 1.055, 2.4) : b / 12.92;

  return {
    x: r * 0.4124 + g * 0.3576 + b * 0.1805,
    y: r * 0.2126 + g * 0.7152 + b * 0.0722,
    z: r * 0.0193 + g * 0.1194 + b * 0.9505,
  };
}

// XYZ 转 L*a*b*
function xyzToLab(x: number, y: number, z: number): { l: number; a: number; b: number } {
  const refX = 0.95047;
  const refY = 1.0;
  const refZ = 1.08883;

  x /= refX;
  y /= refY;
  z /= refZ;

  x = x > 0.008856 ? Math.pow(x, 1 / 3) : 7.787 * x + 16 / 116;
  y = y > 0.008856 ? Math.pow(y, 1 / 3) : 7.787 * y + 16 / 116;
  z = z > 0.008856 ? Math.pow(z, 1 / 3) : 7.787 * z + 16 / 116;

  return {
    l: 116 * y - 16,
    a: 500 * (x - y),
    b: 200 * (y - z),
  };
}

// CIE76 色差公式（更接近人眼感知）
export function colorDistanceCIE76(c1: string, c2: string): number {
  const r1 = parseInt(c1.slice(1, 3), 16);
  const g1 = parseInt(c1.slice(3, 5), 16);
  const b1 = parseInt(c1.slice(5, 7), 16);
  const r2 = parseInt(c2.slice(1, 3), 16);
  const g2 = parseInt(c2.slice(3, 5), 16);
  const b2 = parseInt(c2.slice(5, 7), 16);

  const { x: x1, y: y1, z: z1 } = rgbToXyz(r1, g1, b1);
  const { x: x2, y: y2, z: z2 } = rgbToXyz(r2, g2, b2);

  const lab1 = xyzToLab(x1, y1, z1);
  const lab2 = xyzToLab(x2, y2, z2);

  return Math.sqrt(
    Math.pow(lab1.l - lab2.l, 2) +
    Math.pow(lab1.a - lab2.a, 2) +
    Math.pow(lab1.b - lab2.b, 2)
  );
}

// 加权 RGB 距离（绿色权重更高，更接近人眼感知）
export function weightColorDistance(r1: number, g1: number, b1: number, r2: number, g2: number, b2: number): number {
  const dr = r1 - r2;
  const dg = g1 - g2;
  const db = b1 - b2;
  return 3 * dr * dr + 4 * dg * dg + 2 * db * db;
}

// 预计算色板的 Lab 值（加速匹配）
export interface PaletteLab {
  hex: string;
  name: string;
  l: number;
  a: number;
  b: number;
}

export function precomputePaletteLab(paletteColors: { hex: string; name: string }[]): PaletteLab[] {
  return paletteColors.map((c) => {
    const r = parseInt(c.hex.slice(1, 3), 16);
    const g = parseInt(c.hex.slice(3, 5), 16);
    const b = parseInt(c.hex.slice(5, 7), 16);
    const { x, y, z } = rgbToXyz(r, g, b);
    const lab = xyzToLab(x, y, z);
    return { hex: c.hex, name: c.name, l: lab.l, a: lab.a, b: lab.b };
  });
}

// 用预计算 Lab 值快速匹配
export function matchToPaletteFast(
  r: number, g: number, b: number,
  paletteLab: PaletteLab[]
): { hex: string; name: string } {
  const { x, y, z } = rgbToXyz(r, g, b);
  const lab = xyzToLab(x, y, z);
  let best = paletteLab[0];
  let bestDist = Infinity;
  for (const c of paletteLab) {
    const dist = (lab.l - c.l) ** 2 + (lab.a - c.a) ** 2 + (lab.b - c.b) ** 2;
    if (dist < bestDist) {
      bestDist = dist;
      best = c;
    }
  }
  return { hex: best.hex, name: best.name };
}

// 将颜色匹配到最近色板（使用 CIE76）
export function matchToPalette(
  hex: string,
  paletteColors: { hex: string; name: string }[]
): { hex: string; name: string; distance: number } {
  let best = paletteColors[0];
  let bestDist = Infinity;
  for (const c of paletteColors) {
    const dist = colorDistanceCIE76(hex, c.hex);
    if (dist < bestDist) {
      bestDist = dist;
      best = c;
    }
  }
  return { hex: best.hex, name: best.name, distance: bestDist };
}

// 中值切割量化 - 简化版
export function quantizeColors(
  imageData: ImageData,
  maxColors: number
): string[] {
  const data = imageData.data;
  const colorMap = new Map<string, number>();

  for (let i = 0; i < data.length; i += 4) {
    const r = Math.round(data[i] / 16) * 16;
    const g = Math.round(data[i + 1] / 16) * 16;
    const b = Math.round(data[i + 2] / 16) * 16;
    const key = `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;
    colorMap.set(key, (colorMap.get(key) || 0) + 1);
  }

  const sorted = [...colorMap.entries()].sort((a, b) => b[1] - a[1]);
  return sorted.slice(0, maxColors).map(([c]) => c);
}