import { useEditorStore, type ToolType } from '@/stores/useEditorStore';
import { useProjectStore } from '@/stores/useProjectStore';
import {
  Brush,
  Eraser,
  PaintBucket,
  Pipette,
  Undo2,
  Redo2,
} from 'lucide-react';
import clsx from 'clsx';

const tools: { type: ToolType; icon: typeof Brush; label: string }[] = [
  { type: 'brush', icon: Brush, label: '画笔' },
  { type: 'eraser', icon: Eraser, label: '橡皮擦' },
  { type: 'fill', icon: PaintBucket, label: '填充' },
  { type: 'eyedropper', icon: Pipette, label: '吸色' },
];

export default function ToolBar() {
  const { activeTool, setActiveTool } = useEditorStore();
  const { undo, redo, undoStack, redoStack } = useProjectStore();

  return (
    <div className="flex flex-col items-center gap-1.5 py-3 px-2 bg-white border-r border-stone-200 shrink-0">
      {tools.map((tool) => {
        const Icon = tool.icon;
        const isActive = activeTool === tool.type;
        return (
          <button
            key={tool.type}
            onClick={() => {
              setActiveTool(tool.type);
            }}
            title={tool.label}
            className={clsx(
              'w-10 h-10 flex items-center justify-center rounded-xl transition-all duration-150',
              isActive
                ? 'bg-brand-500 text-white shadow-md shadow-brand-200'
                : 'text-stone-400 hover:bg-stone-100 hover:text-stone-600'
            )}
          >
            <Icon className="w-5 h-5" />
          </button>
        );
      })}

      {/* 分割线 */}
      <div className="w-6 h-px bg-stone-200 my-1.5" />

      <button
        onClick={() => undo()}
        disabled={undoStack.length === 0}
        title="撤销"
        className={clsx(
          'w-10 h-10 flex items-center justify-center rounded-xl transition-all duration-150',
          undoStack.length > 0
            ? 'text-stone-500 hover:bg-stone-100 hover:text-stone-700'
            : 'text-stone-300 cursor-not-allowed'
        )}
      >
        <Undo2 className="w-5 h-5" />
      </button>

      <button
        onClick={() => redo()}
        disabled={redoStack.length === 0}
        title="重做"
        className={clsx(
          'w-10 h-10 flex items-center justify-center rounded-xl transition-all duration-150',
          redoStack.length > 0
            ? 'text-stone-500 hover:bg-stone-100 hover:text-stone-700'
            : 'text-stone-300 cursor-not-allowed'
        )}
      >
        <Redo2 className="w-5 h-5" />
      </button>
    </div>
  );
}