import { useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useProjectStore } from '@/stores/useProjectStore';
import { useUIStore } from '@/stores/useUIStore';
import { useEditorStore } from '@/stores/useEditorStore';
import { processImageToGrid } from '@/utils/imageProcessor';
import { exportAsPNG, exportAsJPG, exportForPrint, saveProjectFile } from '@/utils/exportUtils';
import SettingsBar from '@/components/editor/SettingsBar';
import ToolBar from '@/components/editor/ToolBar';
import ColorPalette from '@/components/editor/ColorPalette';
import PreviewPanel from '@/components/editor/PreviewPanel';
import CanvasArea from '@/components/editor/CanvasArea';
import { ArrowLeft, ImagePlus, Save, Printer, FileImage, FileDown, Eye } from 'lucide-react';
import clsx from 'clsx';

export default function EditorPage() {
  const navigate = useNavigate();
  const { currentProject, setCurrentProject, createNewProject } = useProjectStore();
  const { previewPanelOpen, togglePreviewPanel } = useUIStore();
  const { isProcessing, setIsProcessing } = useEditorStore();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleNameChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!currentProject) return;
      setCurrentProject({ ...currentProject, name: e.target.value });
    },
    [currentProject, setCurrentProject]
  );

  const handleImportImage = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  const handleFileChange = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file || !currentProject) return;

      setIsProcessing(true);
      try {
        const reader = new FileReader();
        reader.onload = async (ev) => {
          const src = ev.target?.result as string;
          const result = await processImageToGrid(
            src,
            currentProject.width,
            currentProject.height
          );
          const updated = {
            ...currentProject,
            originalImage: src,
            gridData: result.gridData,
            palette: result.palette.map((c) => ({ ...c, brand: '' })),
            thumbnail: result.thumbnail,
            updatedAt: Date.now(),
          };
          setCurrentProject(updated);
        };
        reader.readAsDataURL(file);
      } finally {
        setIsProcessing(false);
      }
    },
    [currentProject, setIsProcessing, setCurrentProject]
  );

  // 如果没有项目，显示空状态
  if (!currentProject) {
    return (
      <div className="flex flex-col items-center justify-center h-[calc(100vh-64px)] bg-stone-50 gap-4">
        <div className="w-16 h-16 rounded-2xl bg-stone-100 flex items-center justify-center">
          <FileImage className="w-8 h-8 text-stone-400" />
        </div>
        <p className="text-stone-500 text-sm">请先创建或导入工程</p>
        <button
          onClick={() => navigate('/')}
          className="flex items-center gap-2 px-4 py-2 bg-brand-500 text-white rounded-xl text-sm font-medium hover:bg-brand-600 transition-colors shadow-sm"
        >
          <ArrowLeft className="w-4 h-4" />
          返回首页
        </button>
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col bg-stone-50">
      {/* 顶部栏：工程名 + 操作按钮 */}
      <div className="flex items-center justify-between px-4 py-2 bg-white border-b border-stone-200 shrink-0">
        <div className="flex items-center gap-3">
          <button
            onClick={() => navigate('/')}
            className="p-1.5 rounded-lg text-stone-400 hover:text-stone-600 hover:bg-stone-100 transition-colors"
            title="返回首页"
          >
            <ArrowLeft className="w-4 h-4" />
          </button>
          <input
            value={currentProject.name}
            onChange={handleNameChange}
            className="text-sm font-medium text-stone-800 bg-transparent border-none outline-none focus:bg-stone-50 focus:px-2 py-1 rounded-md transition-colors max-w-[240px]"
          />
          <span className="text-xs text-stone-400">
            {currentProject.width}×{currentProject.height}
          </span>
        </div>

        <div className="flex items-center gap-1.5">
          {/* 预览开关 */}
          <button
            onClick={togglePreviewPanel}
            className={clsx(
              'flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium transition-colors',
              previewPanelOpen
                ? 'bg-brand-50 text-brand-600'
                : 'text-stone-500 hover:bg-stone-100 hover:text-stone-700'
            )}
          >
            <Eye className="w-3.5 h-3.5" />
            预览
          </button>

          {/* 导入图片 */}
          <button
            onClick={handleImportImage}
            disabled={isProcessing}
            className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium text-stone-500 hover:bg-stone-100 hover:text-stone-700 transition-colors"
          >
            <ImagePlus className="w-3.5 h-3.5" />
            导入
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={handleFileChange}
          />

          <div className="w-px h-5 bg-stone-200" />

          {/* 导出按钮组 */}
          <button
            onClick={() => exportAsPNG(currentProject)}
            className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium text-stone-500 hover:bg-stone-100 hover:text-stone-700 transition-colors"
            title="导出 PNG"
          >
            <FileImage className="w-3.5 h-3.5" />
            PNG
          </button>
          <button
            onClick={() => exportAsJPG(currentProject)}
            className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium text-stone-500 hover:bg-stone-100 hover:text-stone-700 transition-colors"
            title="导出 JPG"
          >
            <FileDown className="w-3.5 h-3.5" />
            JPG
          </button>
          <button
            onClick={() => exportForPrint(currentProject, 'A4')}
            className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium text-stone-500 hover:bg-stone-100 hover:text-stone-700 transition-colors"
            title="导出打印版"
          >
            <Printer className="w-3.5 h-3.5" />
            打印
          </button>
          <button
            onClick={() => saveProjectFile(currentProject)}
            className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium bg-brand-500 text-white hover:bg-brand-600 transition-colors shadow-sm"
            title="保存工程"
          >
            <Save className="w-3.5 h-3.5" />
            保存
          </button>
        </div>
      </div>

      {/* SettingsBar */}
      <SettingsBar />

      {/* 主体区域：ToolBar + CanvasArea + PreviewPanel */}
      <div className="flex-1 flex overflow-hidden min-h-0">
        <ToolBar />
        <CanvasArea />
        <PreviewPanel />
      </div>

      {/* ColorPalette - 固定高度 100px，内容超出可滚动 */}
      <div className="bg-white border-t border-stone-200 overflow-y-auto" style={{ height: '100px' }}>
        <ColorPalette />
      </div>
    </div>
  );
}