import { useNavigate } from 'react-router-dom';
import { ImagePlus, FilePlus, Clock, Trash2 } from 'lucide-react';
import { useProjectStore } from '../stores/useProjectStore';
import { useUIStore } from '../stores/useUIStore';
import { useRef } from 'react';
import clsx from 'clsx';

export default function HomePage() {
  const navigate = useNavigate();
  const { recentProjects, removeRecentProject, setCurrentProject, createNewProject } = useProjectStore();
  const { showNewbieGuide, setShowNewbieGuide } = useUIStore();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleImport = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        const project = createNewProject(52, 52);
        project.originalImage = reader.result as string;
        setCurrentProject(project);
        navigate('/editor');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleNewProject = () => {
    createNewProject(52, 52);
    navigate('/editor');
  };

  const handleOpenProject = (id: string) => {
    const project = recentProjects.find((p) => p.id === id);
    if (project) {
      setCurrentProject(project);
      navigate('/editor');
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 py-8 sm:py-12">
      {/* Hero Section */}
      <div className="text-center mb-10 sm:mb-16">
        <div className="inline-flex items-center justify-center w-16 h-16 sm:w-20 sm:h-20 rounded-2xl bg-gradient-to-br from-brand-500 to-warm-500 shadow-lg mb-5 sm:mb-6">
          <svg className="w-8 h-8 sm:w-10 sm:h-10 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
            <circle cx="6" cy="6" r="2" />
            <circle cx="18" cy="6" r="2" />
            <circle cx="12" cy="12" r="2" />
            <circle cx="6" cy="18" r="2" />
            <circle cx="18" cy="18" r="2" />
            <rect x="2" y="2" width="20" height="20" rx="4" />
          </svg>
        </div>
        <h1 className="text-3xl sm:text-4xl lg:text-5xl font-display font-bold text-stone-800 mb-3 sm:mb-4">
          拼豆图纸工坊
        </h1>
        <p className="text-base sm:text-lg text-stone-500 max-w-md mx-auto leading-relaxed">
          将图片转为拼豆图纸 · 匹配色号统计用量 · 从零设计创作
        </p>
      </div>

      {/* Quick Actions */}
      <div className="grid sm:grid-cols-2 gap-4 sm:gap-6 max-w-2xl mx-auto mb-10 sm:mb-16">
        <button
          onClick={handleImport}
          className="group relative overflow-hidden rounded-2xl bg-gradient-to-br from-brand-500 to-brand-600 p-6 sm:p-8 text-left text-white shadow-lg hover:shadow-xl transition-all duration-300 hover:-translate-y-0.5"
        >
          <div className="relative z-10">
            <div className="w-12 h-12 rounded-xl bg-white/20 flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
              <ImagePlus className="w-6 h-6" />
            </div>
            <h3 className="text-lg sm:text-xl font-semibold mb-1">导入图片</h3>
            <p className="text-brand-100 text-sm">JPG / PNG / GIF，自动转换拼豆图纸</p>
          </div>
          <div className="absolute -right-6 -bottom-6 w-32 h-32 bg-white/5 rounded-full group-hover:scale-150 transition-transform duration-500" />
        </button>

        <button
          onClick={handleNewProject}
          className="group relative overflow-hidden rounded-2xl bg-gradient-to-br from-warm-500 to-warm-600 p-6 sm:p-8 text-left text-white shadow-lg hover:shadow-xl transition-all duration-300 hover:-translate-y-0.5"
        >
          <div className="relative z-10">
            <div className="w-12 h-12 rounded-xl bg-white/20 flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
              <FilePlus className="w-6 h-6" />
            </div>
            <h3 className="text-lg sm:text-xl font-semibold mb-1">新建空白图纸</h3>
            <p className="text-warm-100 text-sm">选择尺寸，从零开始设计创作</p>
          </div>
          <div className="absolute -right-6 -bottom-6 w-32 h-32 bg-white/5 rounded-full group-hover:scale-150 transition-transform duration-500" />
        </button>

        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          className="hidden"
          onChange={handleFileChange}
        />
      </div>

      {/* Recent Projects */}
      {recentProjects.length > 0 && (
        <div className="max-w-4xl mx-auto">
          <div className="flex items-center gap-2 mb-4">
            <Clock className="w-4 h-4 text-stone-400" />
            <h2 className="text-sm font-medium text-stone-500">最近工程</h2>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 sm:gap-4">
            {recentProjects.map((project) => (
              <div
                key={project.id}
                onClick={() => handleOpenProject(project.id)}
                className="group relative rounded-xl bg-white border border-stone-200 overflow-hidden cursor-pointer hover:shadow-md hover:border-brand-200 transition-all"
              >
                <div className="aspect-square bg-stone-50 flex items-center justify-center p-2">
                  {project.thumbnail ? (
                    <img
                      src={project.thumbnail}
                      alt={project.name}
                      className="w-full h-full object-contain"
                    />
                  ) : (
                    <div className="grid grid-cols-8 gap-0.5 w-full h-full">
                      {Array.from({ length: 64 }).map((_, i) => (
                        <div
                          key={i}
                          className="bg-brand-100 rounded-sm"
                          style={{ opacity: Math.random() * 0.5 + 0.3 }}
                        />
                      ))}
                    </div>
                  )}
                </div>
                <div className="p-2.5">
                  <p className="text-xs font-medium text-stone-700 truncate">
                    {project.name}
                  </p>
                  <p className="text-xs text-stone-400 mt-0.5">
                    {new Date(project.updatedAt).toLocaleDateString('zh-CN')}
                  </p>
                </div>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    removeRecentProject(project.id);
                  }}
                  className="absolute top-2 right-2 w-7 h-7 rounded-lg bg-white/80 backdrop-blur-sm flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-50 hover:text-red-500"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Newbie Guide */}
      {showNewbieGuide && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 max-w-md w-[calc(100%-2rem)] bg-white rounded-2xl shadow-2xl border border-stone-200 p-5 z-40 animate-in slide-in-from-bottom-4">
          <div className="flex items-start gap-3">
            <div className="w-8 h-8 rounded-lg bg-brand-100 flex items-center justify-center flex-shrink-0">
              <svg className="w-4 h-4 text-brand-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="12" cy="12" r="10" />
                <path d="M12 16v-4M12 8h.01" />
              </svg>
            </div>
            <div className="flex-1 min-w-0">
              <h4 className="text-sm font-semibold text-stone-800 mb-1">快速上手</h4>
              <p className="text-xs text-stone-500 leading-relaxed">
                点击「导入图片」上传图片自动生成拼豆图纸，或「新建空白图纸」从零创作。支持自由编辑、色号统计、一键导出发货。
              </p>
            </div>
            <button
              onClick={() => setShowNewbieGuide(false)}
              className="text-stone-400 hover:text-stone-600 p-1"
            >
              <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M18 6L6 18M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}