// 图片处理引擎 - 将图片转换为点阵图纸
import { matchToPaletteFast, precomputePaletteLab, getAllColors } from './palette';

export interface ProcessResult {
  gridData: number[][];
  palette: { index: number; hex: string; name: string; count: number }[];
  thumbnail: string;
}

// 将图片加载为 ImageData
export function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

// 调整图片尺寸（保持锐利，禁用平滑）
function resizeImage(
  img: HTMLImageElement,
  maxWidth: number,
  maxHeight: number
): { canvas: HTMLCanvasElement; ctx: CanvasRenderingContext2D } {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d')!;
  const ratio = Math.min(maxWidth / img.width, maxHeight / img.height, 1);
  canvas.width = Math.round(img.width * ratio);
  canvas.height = Math.round(img.height * ratio);
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
  return { canvas, ctx };
}

// 获取像素数据
function getPixelData(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number
): ImageData {
  return ctx.getImageData(0, 0, width, height);
}

// 增强对比度和边缘（自适应）
function enhanceContrast(data: Uint8ClampedArray, w: number, h: number): void {
  // 计算直方图
  let min = 255, max = 0;
  for (let i = 0; i < data.length; i += 4) {
    const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
    if (avg < min) min = avg;
    if (avg > max) max = avg;
  }

  // 如果对比度已经很好，不做处理
  const range = max - min;
  if (range > 150) return;

  // 拉伸对比度到全范围
  const scale = 255 / (range || 1);
  for (let i = 0; i < data.length; i += 4) {
    data[i] = Math.max(0, Math.min(255, (data[i] - min) * scale));
    data[i + 1] = Math.max(0, Math.min(255, (data[i + 1] - min) * scale));
    data[i + 2] = Math.max(0, Math.min(255, (data[i + 2] - min) * scale));
  }
}

// 处理图片 -> 点阵图纸
export async function processImageToGrid(
  imageSrc: string,
  gridWidth: number,
  gridHeight: number,
  _paletteName?: string
): Promise<ProcessResult> {
  const img = await loadImage(imageSrc);

  // 预计算 221 色色板的 Lab 值（只需一次）
  const allColors = getAllColors();
  const paletteLab = precomputePaletteLab(allColors);

  // 使用高分辨率处理，捕获更多细节（3x 网格尺寸）
  const processWidth = Math.round(gridWidth * 3);
  const processHeight = Math.round(gridHeight * 3);

  const { canvas, ctx } = resizeImage(img, processWidth, processHeight);
  const imageData = getPixelData(ctx, canvas.width, canvas.height);
  const pixelData = imageData.data;
  const w = canvas.width;
  const h = canvas.height;

  // 增强对比度，使线条更清晰
  enhanceContrast(pixelData, w, h);

  // 创建网格映射
  const gridData: number[][] = [];
  const cellW = w / gridWidth;
  const cellH = h / gridHeight;

  // 记录已使用的色板颜色
  const usedColorMap = new Map<string, { hex: string; name: string }>();

  for (let gy = 0; gy < gridHeight; gy++) {
    const row: number[] = [];
    for (let gx = 0; gx < gridWidth; gx++) {
      // 计算此格子覆盖的像素范围
      const startX = Math.floor(gx * cellW);
      const endX = Math.min(Math.floor((gx + 1) * cellW), w);
      const startY = Math.floor(gy * cellH);
      const endY = Math.min(Math.floor((gy + 1) * cellH), h);

      const cellPixels: { r: number; g: number; b: number }[] = [];

      for (let py = startY; py < endY; py++) {
        for (let px = startX; px < endX; px++) {
          const idx = (py * w + px) * 4;
          cellPixels.push({
            r: pixelData[idx],
            g: pixelData[idx + 1],
            b: pixelData[idx + 2],
          });
        }
      }

      if (cellPixels.length === 0) {
        row.push(-1);
        continue;
      }

      // 策略：计算像素的平均颜色，然后直接匹配到最近色板
      // 颜色平均法比多数决法更能保留渐变感和色彩准确性
      let totalR = 0, totalG = 0, totalB = 0;
      for (const p of cellPixels) {
        totalR += p.r;
        totalG += p.g;
        totalB += p.b;
      }

      const meanR = Math.round(totalR / cellPixels.length);
      const meanG = Math.round(totalG / cellPixels.length);
      const meanB = Math.round(totalB / cellPixels.length);

      // 直接匹配到 221 色板（用预计算 Lab 加速）
      const matched = matchToPaletteFast(meanR, meanG, meanB, paletteLab);

      // 注册已使用的颜色
      if (!usedColorMap.has(matched.hex)) {
        usedColorMap.set(matched.hex, matched);
      }

      const colorIndex = [...usedColorMap.values()].findIndex((c) => c.hex === matched.hex);
      row.push(colorIndex);
    }
    gridData.push(row);
  }

  // 统计颜色用量
  const palette = [...usedColorMap.values()].map((c, i) => {
    let count = 0;
    for (const row of gridData) {
      for (const cell of row) {
        if (cell === i) count++;
      }
    }
    return { index: i, hex: c.hex, name: c.name, count };
  });

  // 生成缩略图
  const thumbCanvas = document.createElement('canvas');
  thumbCanvas.width = 200;
  thumbCanvas.height = Math.round(200 * (gridHeight / gridWidth));
  const thumbCtx = thumbCanvas.getContext('2d')!;
  const cellSize = thumbCanvas.width / gridWidth;

  for (let y = 0; y < gridHeight; y++) {
    for (let x = 0; x < gridWidth; x++) {
      const ci = gridData[y][x];
      if (ci >= 0 && ci < palette.length) {
        thumbCtx.fillStyle = palette[ci].hex;
        thumbCtx.fillRect(
          x * cellSize,
          y * cellSize,
          Math.ceil(cellSize),
          Math.ceil(cellSize)
        );
      }
    }
  }

  const thumbnail = thumbCanvas.toDataURL('image/png');

  return { gridData, palette, thumbnail };
}

// 应用滤镜到原始图片
export function applyFilter(
  imageData: ImageData,
  filterType: 'none' | 'pixelate' | 'cartoon' | 'lineart',
  brightness: number,
  contrast: number
): ImageData {
  const data = new Uint8ClampedArray(imageData.data);
  const w = imageData.width;
  const h = imageData.height;

  // 亮度和对比度调整
  const brightnessFactor = 1 + brightness / 100;
  const contrastFactor = (259 * (1 + contrast / 100) + 255) / (259 * (1 - contrast / 100) + 255);

  for (let i = 0; i < data.length; i += 4) {
    let r = data[i];
    let g = data[i + 1];
    let b = data[i + 2];

    // 亮度
    r = r * brightnessFactor;
    g = g * brightnessFactor;
    b = b * brightnessFactor;

    // 对比度
    r = contrastFactor * (r - 128) + 128;
    g = contrastFactor * (g - 128) + 128;
    b = contrastFactor * (b - 128) + 128;

    data[i] = Math.max(0, Math.min(255, r));
    data[i + 1] = Math.max(0, Math.min(255, g));
    data[i + 2] = Math.max(0, Math.min(255, b));
  }

  if (filterType === 'pixelate') {
    for (let i = 0; i < data.length; i += 4) {
      data[i] = Math.round(data[i] / 32) * 32;
      data[i + 1] = Math.round(data[i + 1] / 32) * 32;
      data[i + 2] = Math.round(data[i + 2] / 32) * 32;
    }
  } else if (filterType === 'cartoon') {
    for (let i = 0; i < data.length; i += 4) {
      data[i] = Math.round(data[i] / 48) * 48;
      data[i + 1] = Math.round(data[i + 1] / 48) * 48;
      data[i + 2] = Math.round(data[i + 2] / 48) * 48;
    }
  } else if (filterType === 'lineart') {
    for (let i = 0; i < data.length; i += 4) {
      const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
      const val = avg > 128 ? 255 : 0;
      data[i] = val;
      data[i + 1] = val;
      data[i + 2] = val;
    }
  }

  return new ImageData(data, w, h);
}