import { create } from 'zustand';
import { getAllColors } from '@/utils/palette';

export interface ProjectSettings {
  showGrid: boolean;
  beadType: 'large' | 'small';
  zoom: number;
  offsetX: number;
  offsetY: number;
}

export interface ColorInfo {
  index: number;
  hex: string;
  name: string;
  brand: string;
  count: number;
}

export interface Project {
  id: string;
  name: string;
  createdAt: number;
  updatedAt: number;
  width: number;
  height: number;
  gridData: number[][];
  palette: ColorInfo[];
  originalImage?: string;
  thumbnail?: string;
  settings: ProjectSettings;
}

interface ProjectStore {
  currentProject: Project | null;
  recentProjects: Project[];
  undoStack: Project[];
  redoStack: Project[];
  setCurrentProject: (project: Project | null) => void;
  addRecentProject: (project: Project) => void;
  removeRecentProject: (id: string) => void;
  updateGrid: (x: number, y: number, colorIndex: number) => void;
  fillGrid: (x: number, y: number, colorIndex: number) => void;
  pushUndo: () => void;
  undo: () => void;
  redo: () => void;
  createNewProject: (width: number, height: number) => Project;
  expandGrid: (amount?: number) => void;
  shrinkGrid: () => void;
  expandSide: (side: 'top' | 'bottom' | 'left' | 'right') => void;
  shrinkSide: (side: 'top' | 'bottom' | 'left' | 'right') => void;
  resizeSide: (side: 'top' | 'bottom' | 'left' | 'right', delta: number) => void;
  updateSettings: (settings: Partial<ProjectSettings>) => void;
}

function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

function createEmptyGrid(width: number, height: number): number[][] {
  return Array.from({ length: height }, () => Array(width).fill(-1));
}

export const useProjectStore = create<ProjectStore>((set, get) => ({
  currentProject: null,
  recentProjects: [],
  undoStack: [],
  redoStack: [],

  setCurrentProject: (project) => set({ currentProject: project }),

  addRecentProject: (project) =>
    set((state) => {
      const filtered = state.recentProjects.filter((p) => p.id !== project.id);
      return {
        recentProjects: [project, ...filtered].slice(0, 20),
      };
    }),

  removeRecentProject: (id) =>
    set((state) => ({
      recentProjects: state.recentProjects.filter((p) => p.id !== id),
    })),

  updateGrid: (x, y, colorIndex) =>
    set((state) => {
      if (!state.currentProject) return state;
      const grid = state.currentProject.gridData.map((row) => [...row]);
      if (y >= 0 && y < grid.length && x >= 0 && x < grid[0].length) {
        grid[y][x] = colorIndex;
      }
      const updated = {
        ...state.currentProject,
        gridData: grid,
        updatedAt: Date.now(),
      };
      return { currentProject: updated };
    }),

  fillGrid: (startX, startY, colorIndex) =>
    set((state) => {
      if (!state.currentProject) return state;
      const grid = state.currentProject.gridData.map((row) => [...row]);
      const h = grid.length;
      const w = grid[0].length;
      const targetColor = grid[startY]?.[startX];
      if (targetColor === colorIndex || targetColor === undefined) return state;

      const stack: [number, number][] = [[startX, startY]];
      const visited = new Set<string>();

      while (stack.length > 0) {
        const [cx, cy] = stack.pop()!;
        const key = `${cx},${cy}`;
        if (visited.has(key)) continue;
        visited.add(key);
        if (cy < 0 || cy >= h || cx < 0 || cx >= w) continue;
        if (grid[cy][cx] !== targetColor) continue;
        grid[cy][cx] = colorIndex;
        stack.push([cx - 1, cy], [cx + 1, cy], [cx, cy - 1], [cx, cy + 1]);
      }

      const updated = {
        ...state.currentProject,
        gridData: grid,
        updatedAt: Date.now(),
      };
      return { currentProject: updated };
    }),

  pushUndo: () =>
    set((state) => {
      if (!state.currentProject) return state;
      return {
        undoStack: [...state.undoStack.slice(-30), state.currentProject],
        redoStack: [],
      };
    }),

  undo: () =>
    set((state) => {
      if (state.undoStack.length === 0) return state;
      const prev = state.undoStack[state.undoStack.length - 1];
      return {
        undoStack: state.undoStack.slice(0, -1),
        redoStack: [...state.redoStack, state.currentProject!],
        currentProject: prev,
      };
    }),

  redo: () =>
    set((state) => {
      if (state.redoStack.length === 0) return state;
      const next = state.redoStack[state.redoStack.length - 1];
      return {
        redoStack: state.redoStack.slice(0, -1),
        undoStack: [...state.undoStack, state.currentProject!],
        currentProject: next,
      };
    }),

  createNewProject: (width, height) => {
    const allColors = getAllColors();
    const project: Project = {
      id: generateId(),
      name: `未命名图纸 ${width}x${height}`,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      width,
      height,
      gridData: createEmptyGrid(width, height),
      palette: allColors.map((c, i) => ({
        index: i,
        hex: c.hex,
        name: c.name,
        brand: '通用',
        count: 0,
      })),
      settings: {
        showGrid: true,
        beadType: 'small',
        zoom: 1,
        offsetX: 0,
        offsetY: 0,
      },
    };
    set({ currentProject: project });
    return project;
  },

  expandGrid: (amount = 1) =>
    set((state) => {
      if (!state.currentProject) return state;
      const { gridData, width, height } = state.currentProject;
      const newW = width + amount * 2;
      const newH = height + amount * 2;

      // 在四边添加空行/空列
      const emptyRow = Array(newW).fill(-1);
      const newGrid: number[][] = [];

      // 顶部空行
      for (let i = 0; i < amount; i++) newGrid.push([...emptyRow]);

      // 中间行：左右加空列
      for (const row of gridData) {
        const newRow = [...Array(amount).fill(-1), ...row, ...Array(amount).fill(-1)];
        newGrid.push(newRow);
      }

      // 底部空行
      for (let i = 0; i < amount; i++) newGrid.push([...emptyRow]);

      const updated: Project = {
        ...state.currentProject,
        width: newW,
        height: newH,
        gridData: newGrid,
        updatedAt: Date.now(),
      };
      return { currentProject: updated };
    }),

  shrinkGrid: () =>
    set((state) => {
      if (!state.currentProject) return state;
      let { gridData, width, height } = state.currentProject;

      // 至少保留 1×1
      if (width <= 1 || height <= 1) return state;

      let topClear = true;
      let bottomClear = true;
      let leftClear = true;
      let rightClear = true;

      // 检查顶行
      for (let x = 0; x < width; x++) {
        if (gridData[0][x] !== -1) { topClear = false; break; }
      }
      // 检查底行
      for (let x = 0; x < width; x++) {
        if (gridData[height - 1][x] !== -1) { bottomClear = false; break; }
      }
      // 检查左列
      for (let y = 0; y < height; y++) {
        if (gridData[y][0] !== -1) { leftClear = false; break; }
      }
      // 检查右列
      for (let y = 0; y < height; y++) {
        if (gridData[y][width - 1] !== -1) { rightClear = false; break; }
      }

      // 至少要能去掉一边
      if (!topClear && !bottomClear && !leftClear && !rightClear) return state;

      // 确定新边界
      const newTop = topClear ? 1 : 0;
      const newBottom = bottomClear ? height - 1 : height;
      const newLeft = leftClear ? 1 : 0;
      const newRight = rightClear ? width - 1 : width;

      const newW = newRight - newLeft;
      const newH = newBottom - newTop;

      // 保证不缩到 0
      if (newW < 1 || newH < 1) return state;

      // 裁剪网格
      const newGrid = gridData
        .slice(newTop, newBottom)
        .map((row) => row.slice(newLeft, newRight));

      const updated: Project = {
        ...state.currentProject,
        width: newW,
        height: newH,
        gridData: newGrid,
        updatedAt: Date.now(),
      };
      return { currentProject: updated };
    }),

  expandSide: (side) =>
    set((state) => {
      if (!state.currentProject) return state;
      const { gridData, width, height } = state.currentProject;

      let newGrid: number[][];
      let newW = width;
      let newH = height;

      if (side === 'top') {
        newGrid = [Array(width).fill(-1), ...gridData];
        newH = height + 1;
      } else if (side === 'bottom') {
        newGrid = [...gridData, Array(width).fill(-1)];
        newH = height + 1;
      } else if (side === 'left') {
        newGrid = gridData.map((row) => [-1, ...row]);
        newW = width + 1;
      } else {
        newGrid = gridData.map((row) => [...row, -1]);
        newW = width + 1;
      }

      const updated: Project = {
        ...state.currentProject,
        width: newW,
        height: newH,
        gridData: newGrid,
        updatedAt: Date.now(),
      };
      return { currentProject: updated };
    }),

  shrinkSide: (side) =>
    set((state) => {
      if (!state.currentProject) return state;
      const { gridData, width, height } = state.currentProject;
      if (width <= 1 || height <= 1) return state;

      let canShrink = false;
      let newGrid: number[][];

      if (side === 'top') {
        canShrink = gridData[0].every((c) => c === -1);
        if (!canShrink) return state;
        newGrid = gridData.slice(1);
      } else if (side === 'bottom') {
        canShrink = gridData[height - 1].every((c) => c === -1);
        if (!canShrink) return state;
        newGrid = gridData.slice(0, -1);
      } else if (side === 'left') {
        canShrink = gridData.every((row) => row[0] === -1);
        if (!canShrink) return state;
        newGrid = gridData.map((row) => row.slice(1));
      } else {
        canShrink = gridData.every((row) => row[width - 1] === -1);
        if (!canShrink) return state;
        newGrid = gridData.map((row) => row.slice(0, -1));
      }

      const newW = (side === 'left' || side === 'right') ? width - 1 : width;
      const newH = (side === 'top' || side === 'bottom') ? height - 1 : height;

      const updated: Project = {
        ...state.currentProject,
        width: newW,
        height: newH,
        gridData: newGrid,
        updatedAt: Date.now(),
      };
      return { currentProject: updated };
    }),

  resizeSide: (side, delta) =>
    set((state) => {
      if (!state.currentProject || delta === 0) return state;
      const { gridData, width, height } = state.currentProject;

      let newGrid: number[][];
      let newW = width;
      let newH = height;

      if (delta > 0) {
        // 扩大
        if (side === 'top') {
          newGrid = [...Array(delta).fill(null).map(() => Array(width).fill(-1)), ...gridData];
          newH = height + delta;
        } else if (side === 'bottom') {
          newGrid = [...gridData, ...Array(delta).fill(null).map(() => Array(width).fill(-1))];
          newH = height + delta;
        } else if (side === 'left') {
          newGrid = gridData.map((row) => [...Array(delta).fill(-1), ...row]);
          newW = width + delta;
        } else {
          newGrid = gridData.map((row) => [...row, ...Array(delta).fill(-1)]);
          newW = width + delta;
        }
      } else {
        // 收缩: delta 为负数
        const remove = Math.abs(delta);
        if (side === 'top') {
          // 检查要移除的行是否全为空
          let canRemove = true;
          for (let r = 0; r < remove; r++) {
            if (!gridData[r]?.every((c) => c === -1)) { canRemove = false; break; }
          }
          if (!canRemove) return state;
          if (height - remove < 1) return state;
          newGrid = gridData.slice(remove);
          newH = height - remove;
        } else if (side === 'bottom') {
          let canRemove = true;
          for (let r = 0; r < remove; r++) {
            if (!gridData[height - 1 - r]?.every((c) => c === -1)) { canRemove = false; break; }
          }
          if (!canRemove) return state;
          if (height - remove < 1) return state;
          newGrid = gridData.slice(0, height - remove);
          newH = height - remove;
        } else if (side === 'left') {
          let canRemove = true;
          for (let r = 0; r < height; r++) {
            for (let c = 0; c < remove; c++) {
              if (gridData[r]?.[c] !== -1) { canRemove = false; break; }
            }
            if (!canRemove) break;
          }
          if (!canRemove) return state;
          if (width - remove < 1) return state;
          newGrid = gridData.map((row) => row.slice(remove));
          newW = width - remove;
        } else {
          let canRemove = true;
          for (let r = 0; r < height; r++) {
            for (let c = 0; c < remove; c++) {
              if (gridData[r]?.[width - 1 - c] !== -1) { canRemove = false; break; }
            }
            if (!canRemove) break;
          }
          if (!canRemove) return state;
          if (width - remove < 1) return state;
          newGrid = gridData.map((row) => row.slice(0, width - remove));
          newW = width - remove;
        }
      }

      const updated: Project = {
        ...state.currentProject,
        width: newW,
        height: newH,
        gridData: newGrid,
        updatedAt: Date.now(),
      };
      return { currentProject: updated };
    }),

  updateSettings: (settings) =>
    set((state) => {
      if (!state.currentProject) return state;
      return {
        currentProject: {
          ...state.currentProject,
          settings: { ...state.currentProject.settings, ...settings },
        },
      };
    }),
}));