import { useState, useRef, useCallback, useEffect } from 'react';
import {
  Upload,
  X,
  Image as ImageIcon,
  Grid3x3,
  Palette,
  Play,
  Download,
  Loader2,
  FileImage,
  Trash2,
  CheckCircle2,
  AlertCircle,
  ZoomIn,
} from 'lucide-react';
import { processImageToGrid } from '../utils/imageProcessor';
import type { ProcessResult } from '../utils/imageProcessor';
import clsx from 'clsx';

/* ─── 图片项 ─── */
interface ImageFile {
  id: string;
  file: File;
  src: string;
  name: string;
  result?: ProcessResult;
  error?: string;
  converting: boolean;
}

/* ─── 网格尺寸预设 ─── */
const gridPresets = [
  { label: '52×52', w: 52, h: 52 },
  { label: '78×78', w: 78, h: 78 },
  { label: '104×104', w: 104, h: 104 },
  { label: '52×104', w: 52, h: 104 },
];

/* ─── 主页面 ─── */
export default function BatchProcess() {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dropZoneRef = useRef<HTMLDivElement>(null);

  const [images, setImages] = useState<ImageFile[]>([]);
  const [gridWidth, setGridWidth] = useState(52);
  const [gridHeight, setGridHeight] = useState(52);
  const [isConverting, setIsConverting] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const [previewImage, setPreviewImage] = useState<ImageFile | null>(null);

  /* ─── 添加图片 ─── */
  const addFiles = useCallback((files: FileList | File[]) => {
    const valid: ImageFile[] = [];
    for (const file of Array.from(files)) {
      if (!file.type.startsWith('image/')) continue;
      // 避免重复
      const exists = images.some((img) => img.file.name === file.name && img.file.size === file.size);
      if (exists) continue;
      valid.push({
        id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
        file,
        src: URL.createObjectURL(file),
        name: file.name,
        converting: false,
      });
    }
    if (valid.length > 0) {
      setImages((prev) => [...prev, ...valid]);
    }
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      addFiles(e.target.files);
      e.target.value = '';
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (e.dataTransfer.files.length > 0) {
      addFiles(e.dataTransfer.files);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
  };

  /* ─── 删除图片 ─── */
  const removeImage = (id: string) => {
    setImages((prev) => {
      const img = prev.find((i) => i.id === id);
      if (img) URL.revokeObjectURL(img.src);
      return prev.filter((i) => i.id !== id);
    });
  };

  /* ─── 批量转换 ─── */
  const handleConvertAll = async () => {
    const toConvert = images.filter((img) => !img.result && !img.error && !img.converting);
    if (toConvert.length === 0) return;

    setIsConverting(true);

    for (const img of toConvert) {
      setImages((prev) =>
        prev.map((i) => (i.id === img.id ? { ...i, converting: true } : i))
      );

      try {
        const result = await processImageToGrid(img.src, gridWidth, gridHeight);
        setImages((prev) =>
          prev.map((i) => (i.id === img.id ? { ...i, result, converting: false, error: undefined } : i))
        );
      } catch {
        setImages((prev) =>
          prev.map((i) =>
            i.id === img.id
              ? { ...i, converting: false, error: '转换失败，请重试' }
              : i
          )
        );
      }
    }

    setIsConverting(false);
  };

  /* ─── 全部导出 ─── */
  const handleExportAll = () => {
    const withResult = images.filter((img) => img.result);
    for (const img of withResult) {
      const canvas = document.createElement('canvas');
      const grid = img.result!.gridData;
      const palette = img.result!.palette;
      const h = grid.length;
      const w = grid[0].length;
      const cellSize = 16;
      canvas.width = w * cellSize;
      canvas.height = h * cellSize;
      const ctx = canvas.getContext('2d')!;

      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const ci = grid[y][x];
          if (ci >= 0 && ci < palette.length) {
            ctx.fillStyle = palette[ci].hex;
            ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
          }
        }
      }

      const link = document.createElement('a');
      link.download = img.name.replace(/\.[^.]+$/, '') + '_拼豆图纸.png';
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  const convertedCount = images.filter((img) => img.result).length;
  const hasResults = convertedCount > 0;

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 py-8 sm:py-12">
      {/* 页面标题 */}
      <div className="text-center mb-8 sm:mb-10">
        <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-gradient-to-br from-brand-500 to-warm-500 shadow-lg mb-4">
          <Upload className="w-7 h-7 text-white" />
        </div>
        <h1 className="text-2xl sm:text-3xl font-display font-bold text-stone-800 mb-2">
          批量处理
        </h1>
        <p className="text-sm sm:text-base text-stone-500 max-w-lg mx-auto">
          同时上传多张图片，统一设置后一键转换为拼豆图纸
        </p>
      </div>

      <div className="grid lg:grid-cols-3 gap-6 sm:gap-8">
        {/* ─── 左侧：上传 & 设置 ─── */}
        <div className="lg:col-span-1 space-y-5">
          {/* 上传区域 */}
          <div
            ref={dropZoneRef}
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onClick={() => fileInputRef.current?.click()}
            className={clsx(
              'relative rounded-2xl border-2 border-dashed p-8 text-center cursor-pointer transition-all',
              dragOver
                ? 'border-brand-400 bg-brand-50/60 shadow-inner'
                : 'border-stone-200 bg-white hover:border-brand-300 hover:bg-brand-50/30'
            )}
          >
            <div className="flex flex-col items-center gap-3">
              <div
                className={clsx(
                  'w-12 h-12 rounded-xl flex items-center justify-center transition-colors',
                  dragOver ? 'bg-brand-100 text-brand-500' : 'bg-stone-100 text-stone-400'
                )}
              >
                <Upload className="w-6 h-6" />
              </div>
              <div>
                <p className="text-sm font-medium text-stone-700">
                  {dragOver ? '松开以上传' : '拖拽图片到此处'}
                </p>
                <p className="text-xs text-stone-400 mt-1">或点击选择文件（支持多选）</p>
              </div>
            </div>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              multiple
              className="hidden"
              onChange={handleFileChange}
            />
          </div>

          {/* 设置区域 */}
          <div className="rounded-2xl bg-white border border-stone-200/70 p-5 space-y-5 shadow-sm">
            <h3 className="text-sm font-semibold text-stone-700 flex items-center gap-2">
              <Grid3x3 className="w-4 h-4 text-brand-500" />
              统一设置
            </h3>

            {/* 网格尺寸 */}
            <div>
              <label className="text-xs font-medium text-stone-500 mb-2 block">
                网格尺寸
              </label>
              <div className="grid grid-cols-2 gap-2">
                {gridPresets.map((preset) => (
                  <button
                    key={preset.label}
                    onClick={() => {
                      setGridWidth(preset.w);
                      setGridHeight(preset.h);
                    }}
                    className={clsx(
                      'px-3 py-2 rounded-lg text-xs font-medium border transition-all',
                      gridWidth === preset.w && gridHeight === preset.h
                        ? 'border-brand-300 bg-brand-50 text-brand-600'
                        : 'border-stone-200 text-stone-500 hover:border-stone-300 hover:bg-stone-50'
                    )}
                  >
                    {preset.label}
                  </button>
                ))}
              </div>
              <div className="flex items-center gap-2 mt-2">
                <input
                  type="number"
                  min={8}
                  max={120}
                  value={gridWidth}
                  onChange={(e) => setGridWidth(Math.max(8, Math.min(120, Number(e.target.value) || 8)))}
                  className="w-full px-2.5 py-1.5 rounded-lg border border-stone-200 text-xs text-stone-700 focus:outline-none focus:ring-2 focus:ring-brand-200 focus:border-brand-300"
                  placeholder="宽"
                />
                <span className="text-stone-300 text-xs">×</span>
                <input
                  type="number"
                  min={8}
                  max={120}
                  value={gridHeight}
                  onChange={(e) => setGridHeight(Math.max(8, Math.min(120, Number(e.target.value) || 8)))}
                  className="w-full px-2.5 py-1.5 rounded-lg border border-stone-200 text-xs text-stone-700 focus:outline-none focus:ring-2 focus:ring-brand-200 focus:border-brand-300"
                  placeholder="高"
                />
              </div>
            </div>
          </div>

          {/* 转换按钮 */}
          <button
            onClick={handleConvertAll}
            disabled={images.length === 0 || isConverting}
            className={clsx(
              'w-full inline-flex items-center justify-center gap-2 px-6 py-3 rounded-xl font-medium shadow-sm transition-all duration-200',
              images.length > 0 && !isConverting
                ? 'bg-gradient-to-r from-brand-500 to-warm-500 text-white hover:shadow-md hover:from-brand-600 hover:to-warm-600 active:scale-[0.98]'
                : 'bg-stone-100 text-stone-400 cursor-not-allowed'
            )}
          >
            {isConverting ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                转换中...
              </>
            ) : (
              <>
                <Play className="w-4 h-4" />
                开始批量转换
                {images.length > 0 && ` (${images.length} 张)`}
              </>
            )}
          </button>

          {/* 导出按钮 */}
          {hasResults && (
            <button
              onClick={handleExportAll}
              className="w-full inline-flex items-center justify-center gap-2 px-6 py-3 rounded-xl bg-white border border-brand-200 text-brand-600 font-medium shadow-sm hover:bg-brand-50 hover:border-brand-300 active:scale-[0.98] transition-all duration-200"
            >
              <Download className="w-4 h-4" />
              全部导出 ({convertedCount})
            </button>
          )}
        </div>

        {/* ─── 右侧：图片列表 & 结果 ─── */}
        <div className="lg:col-span-2">
          {images.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 rounded-2xl bg-white border border-stone-200/70">
              <FileImage className="w-12 h-12 text-stone-200 mb-4" />
              <p className="text-sm text-stone-400">暂无上传的图片</p>
              <p className="text-xs text-stone-300 mt-1">拖拽或点击上传区域添加图片</p>
            </div>
          ) : (
            <div className="space-y-3">
              {/* 统计栏 */}
              <div className="flex items-center justify-between px-1">
                <p className="text-xs text-stone-500">
                  共 {images.length} 张图片
                  {hasResults && ` · 已转换 ${convertedCount} 张`}
                </p>
                {images.some((img) => img.result) && (
                  <button
                    onClick={() => {
                      images.forEach((img) => URL.revokeObjectURL(img.src));
                      setImages([]);
                    }}
                    className="text-xs text-stone-400 hover:text-red-500 transition-colors flex items-center gap-1"
                  >
                    <Trash2 className="w-3 h-3" />
                    清空全部
                  </button>
                )}
              </div>

              {/* 图片卡片列表 */}
              {images.map((img) => (
                <div
                  key={img.id}
                  className="rounded-2xl bg-white border border-stone-200/70 overflow-hidden shadow-sm hover:shadow-md transition-shadow"
                >
                  <div className="flex items-start gap-4 p-4">
                    {/* 缩略图 */}
                    <div
                      className={clsx(
                        'shrink-0 w-16 h-16 sm:w-20 sm:h-20 rounded-xl bg-stone-50 overflow-hidden border border-stone-100',
                        img.result && 'cursor-pointer hover:ring-2 hover:ring-brand-300 transition-all'
                      )}
                      onClick={() => {
                        if (img.result) setPreviewImage(img);
                      }}
                      title={img.result ? '点击查看大图预览' : ''}
                    >
                      {img.result ? (
                        <div className="relative w-full h-full group">
                          <PreviewThumbnail result={img.result} />
                          <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center">
                            <ZoomIn className="w-5 h-5 text-white opacity-0 group-hover:opacity-100 transition-opacity" />
                          </div>
                        </div>
                      ) : (
                        <img
                          src={img.src}
                          alt={img.name}
                          className="w-full h-full object-cover"
                        />
                      )}
                    </div>

                    {/* 信息 */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0">
                          <p className="text-sm font-medium text-stone-700 truncate">
                            {img.name}
                          </p>
                          <p className="text-xs text-stone-400 mt-0.5">
                            {(img.file.size / 1024).toFixed(1)} KB
                          </p>
                        </div>
                        <button
                          onClick={() => removeImage(img.id)}
                          className="shrink-0 w-7 h-7 rounded-lg flex items-center justify-center text-stone-400 hover:text-red-500 hover:bg-red-50 transition-colors"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </div>

                      {/* 状态 */}
                      <div className="mt-2">
                        {img.converting && (
                          <span className="inline-flex items-center gap-1 text-xs text-brand-500">
                            <Loader2 className="w-3 h-3 animate-spin" />
                            转换中...
                          </span>
                        )}
                        {img.error && (
                          <span className="inline-flex items-center gap-1 text-xs text-red-500">
                            <AlertCircle className="w-3 h-3" />
                            {img.error}
                          </span>
                        )}
                        {img.result && (
                          <span className="inline-flex items-center gap-1 text-xs text-green-600">
                            <CheckCircle2 className="w-3 h-3" />
                            转换完成 · {img.result.palette.length} 色 ·{' '}
                            {img.result.gridData[0]?.length ?? 0}×{img.result.gridData.length}
                          </span>
                        )}
                        {!img.converting && !img.error && !img.result && (
                          <span className="inline-flex items-center gap-1 text-xs text-stone-400">
                            <ImageIcon className="w-3 h-3" />
                            等待转换
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* 预览弹窗 */}
      {previewImage && (
        <PreviewModal
          image={previewImage}
          onClose={() => setPreviewImage(null)}
        />
      )}
    </div>
  );
}

/* ─── 预览弹窗 ─── */
function PreviewModal({
  image,
  onClose,
}: {
  image: ImageFile;
  onClose: () => void;
}) {
  const result = image.result!;
  const { gridData, palette } = result;
  const h = gridData.length;
  const w = gridData[0]?.length ?? 0;
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // 点击遮罩层关闭
  const handleOverlayClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget) onClose();
  };

  // ESC 关闭
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [onClose]);

  // 渲染大图 Canvas
  const renderCanvas = (canvas: HTMLCanvasElement | null) => {
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const maxDisplaySize = Math.min(500, Math.max(200, w * 8));
    const cellSize = Math.floor(maxDisplaySize / Math.max(w, h));
    const displayW = w * cellSize;
    const displayH = h * cellSize;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = displayW * dpr;
    canvas.height = displayH * dpr;
    canvas.style.width = `${displayW}px`;
    canvas.style.height = `${displayH}px`;
    ctx.scale(dpr, dpr);

    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, displayW, displayH);

    // 绘制每个豆子
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const ci = gridData[y][x];
        if (ci >= 0 && ci < palette.length) {
          // 画圆角方形模拟拼豆效果
          ctx.fillStyle = palette[ci].hex;
          ctx.beginPath();
          const rx = x * cellSize;
          const ry = y * cellSize;
          const r = cellSize * 0.15;
          ctx.roundRect(rx, ry, cellSize, cellSize, r);
          ctx.fill();
        }
      }
    }

    // 网格线（浅色）
    ctx.strokeStyle = 'rgba(0,0,0,0.06)';
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= w; x++) {
      ctx.beginPath();
      ctx.moveTo(x * cellSize, 0);
      ctx.lineTo(x * cellSize, displayH);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * cellSize);
      ctx.lineTo(displayW, y * cellSize);
      ctx.stroke();
    }

    // 10×10 大格子分区线
    ctx.strokeStyle = 'rgba(0,0,0,0.15)';
    ctx.lineWidth = 1.5;
    for (let x = 0; x <= w; x += 10) {
      ctx.beginPath();
      ctx.moveTo(x * cellSize, 0);
      ctx.lineTo(x * cellSize, displayH);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y += 10) {
      ctx.beginPath();
      ctx.moveTo(0, y * cellSize);
      ctx.lineTo(displayW, y * cellSize);
      ctx.stroke();
    }
  };

  // 导出单张
  const handleExport = () => {
    const canvas = document.createElement('canvas');
    const cellSize = 16;
    canvas.width = w * cellSize;
    canvas.height = h * cellSize;
    const ctx = canvas.getContext('2d')!;
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const ci = gridData[y][x];
        if (ci >= 0 && ci < palette.length) {
          ctx.fillStyle = palette[ci].hex;
          ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
        }
      }
    }
    // 10×10 大格子分区线（导出图）
    ctx.strokeStyle = 'rgba(0,0,0,0.12)';
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= w; x += 10) {
      ctx.beginPath();
      ctx.moveTo(x * cellSize, 0);
      ctx.lineTo(x * cellSize, canvas.height);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y += 10) {
      ctx.beginPath();
      ctx.moveTo(0, y * cellSize);
      ctx.lineTo(canvas.width, y * cellSize);
      ctx.stroke();
    }
    const link = document.createElement('a');
    link.download = image.name.replace(/\.[^.]+$/, '') + '_拼豆图纸.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  return (
    <div
      className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4"
      onClick={handleOverlayClick}
    >
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-y-auto animate-in zoom-in-95">
        {/* 头部 */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-stone-100">
          <div className="flex items-center gap-3 min-w-0">
            <ImageIcon className="w-5 h-5 text-brand-500 shrink-0" />
            <h3 className="text-base font-semibold text-stone-800 truncate">
              {image.name}
            </h3>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={handleExport}
              className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-brand-500 text-white text-xs font-medium hover:bg-brand-600 transition-colors"
            >
              <Download className="w-3.5 h-3.5" />
              导出此图
            </button>
            <button
              onClick={onClose}
              className="w-8 h-8 rounded-lg flex items-center justify-center text-stone-400 hover:text-stone-600 hover:bg-stone-100 transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* 内容 */}
        <div className="p-6 space-y-6">
          {/* 预览对比 */}
          <div className="grid md:grid-cols-2 gap-4">
            {/* 原图 */}
            <div className="rounded-xl bg-stone-50 border border-stone-200 overflow-hidden">
              <div className="px-3 py-2 border-b border-stone-100">
                <span className="text-xs font-medium text-stone-500">原图</span>
              </div>
              <div className="flex items-center justify-center p-4 min-h-[200px]">
                <img
                  src={image.src}
                  alt="原图"
                  className="max-w-full max-h-[300px] object-contain rounded-lg"
                />
              </div>
            </div>

            {/* 点阵图 */}
            <div className="rounded-xl bg-stone-50 border border-stone-200 overflow-hidden">
              <div className="px-3 py-2 border-b border-stone-100 flex items-center justify-between">
                <span className="text-xs font-medium text-stone-500">拼豆图纸</span>
                <span className="text-[10px] text-stone-400">
                  {w}×{h} · {palette.length} 色
                </span>
              </div>
              <div className="flex items-center justify-center p-4 min-h-[200px] overflow-auto">
                <canvas
                  ref={renderCanvas}
                  className="rounded-lg shadow-sm"
                  style={{ maxWidth: '100%', height: 'auto' }}
                />
              </div>
            </div>
          </div>

          {/* 色号统计 */}
          <div className="rounded-xl bg-stone-50 border border-stone-200 p-4">
            <h4 className="text-xs font-semibold text-stone-600 mb-3 flex items-center gap-1.5">
              <Palette className="w-3.5 h-3.5" />
              色号统计
            </h4>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
              {palette.map((c) => (
                <div
                  key={c.index}
                  className="flex items-center gap-2 bg-white rounded-lg px-3 py-2 border border-stone-100 shadow-sm"
                >
                  <div
                    className="w-6 h-6 rounded-lg border border-stone-100 shrink-0"
                    style={{ backgroundColor: c.hex }}
                  />
                  <div className="min-w-0">
                    <p className="text-xs font-medium text-stone-700 truncate">{c.name}</p>
                    <p className="text-[10px] text-stone-400">{c.count} 颗</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ─── 结果缩略图 ─── */
function PreviewThumbnail({ result }: { result: ProcessResult }) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const { gridData, palette } = result;

  // 使用 ref 渲染，不依赖 useState 避免重复渲染
  const renderCanvas = (canvas: HTMLCanvasElement | null) => {
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const size = 80;
    canvas.width = size * dpr;
    canvas.height = size * dpr;
    canvas.style.width = `${size}px`;
    canvas.style.height = `${size}px`;
    ctx.scale(dpr, dpr);

    ctx.clearRect(0, 0, size, size);

    const h = gridData.length;
    if (h === 0) return;
    const w = gridData[0].length;
    const cellSize = Math.min(size / w, size / h);
    const totalW = w * cellSize;
    const totalH = h * cellSize;
    const offsetX = (size - totalW) / 2;
    const offsetY = (size - totalH) / 2;

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const ci = gridData[y][x];
        if (ci >= 0 && ci < palette.length) {
          ctx.fillStyle = palette[ci].hex;
          ctx.fillRect(
            offsetX + x * cellSize,
            offsetY + y * cellSize,
            Math.ceil(cellSize),
            Math.ceil(cellSize)
          );
        }
      }
    }
  };

  return <canvas ref={renderCanvas} className="w-full h-full" />;
}