import { useEditorStore } from '@/stores/useEditorStore';
import { useProjectStore } from '@/stores/useProjectStore';
import { Grid3x3, Sun, Moon, Eye, EyeOff, Sparkles, Image as ImageIcon, Scissors, Maximize2, Minimize2 } from 'lucide-react';
import clsx from 'clsx';
import { useCallback } from 'react';

const gridPresets = [
  { label: '26×26', w: 26, h: 26 },
  { label: '52×52', w: 52, h: 52 },
  { label: '78×78', w: 78, h: 78 },
  { label: '104×104', w: 104, h: 104 },
];

const filters = [
  { key: 'none' as const, label: '无', icon: ImageIcon },
  { key: 'pixelate' as const, label: '像素化', icon: Grid3x3 },
  { key: 'cartoon' as const, label: '卡通化', icon: Sparkles },
  { key: 'lineart' as const, label: '线稿', icon: Scissors },
];

export default function SettingsBar() {
  const { currentProject, updateSettings, createNewProject, setCurrentProject, expandGrid, shrinkGrid } = useProjectStore();
  const {
    filterType,
    brightness,
    contrast,
    setFilterType,
    setBrightness,
    setContrast,
  } = useEditorStore();

  const handleGridResize = useCallback(
    (w: number, h: number) => {
      if (!currentProject) return;
      const project = createNewProject(w, h);
      if (currentProject.originalImage) {
        project.originalImage = currentProject.originalImage;
      }
      setCurrentProject(project);
    },
    [currentProject, createNewProject, setCurrentProject]
  );

  if (!currentProject) return null;

  return (
    <div className="flex items-center gap-4 px-4 py-2.5 bg-white border-b border-stone-200 overflow-x-auto shrink-0">
      {/* 网格尺寸 */}
      <div className="flex items-center gap-1.5 shrink-0">
        <Grid3x3 className="w-4 h-4 text-stone-400" />
        <span className="text-xs text-stone-500 font-medium whitespace-nowrap">尺寸</span>
        <div className="flex gap-0.5">
          {gridPresets.map((preset) => {
            const isActive = currentProject.width === preset.w && currentProject.height === preset.h;
            return (
              <button
                key={preset.label}
                onClick={() => handleGridResize(preset.w, preset.h)}
                className={clsx(
                  'px-2.5 py-1 rounded-md text-xs font-medium transition-colors',
                  isActive
                    ? 'bg-brand-500 text-white shadow-sm'
                    : 'text-stone-500 hover:bg-stone-100 hover:text-stone-700'
                )}
              >
                {preset.label}
              </button>
            );
          })}
          {/* 扩大/收缩 */}
          <button
            onClick={() => expandGrid(1)}
            title="扩大图纸（四边各加1格）"
            className="p-1 rounded-md text-stone-400 hover:text-stone-600 hover:bg-stone-100 transition-colors"
          >
            <Maximize2 className="w-3.5 h-3.5" />
          </button>
          <button
            onClick={() => shrinkGrid()}
            title="收缩图纸（移除空白边缘）"
            className="p-1 rounded-md text-stone-400 hover:text-stone-600 hover:bg-stone-100 transition-colors"
          >
            <Minimize2 className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      <div className="w-px h-6 bg-stone-200 shrink-0" />

      {/* 滤镜切换 */}
      <div className="flex items-center gap-1.5 shrink-0">
        <span className="text-xs text-stone-500 font-medium whitespace-nowrap">滤镜</span>
        <div className="flex gap-0.5">
          {filters.map((f) => {
            const Icon = f.icon;
            const isActive = filterType === f.key;
            return (
              <button
                key={f.key}
                onClick={() => setFilterType(f.key)}
                className={clsx(
                  'flex items-center gap-1 px-2.5 py-1 rounded-md text-xs font-medium transition-colors',
                  isActive
                    ? 'bg-brand-500 text-white shadow-sm'
                    : 'text-stone-500 hover:bg-stone-100 hover:text-stone-700'
                )}
              >
                <Icon className="w-3.5 h-3.5" />
                {f.label}
              </button>
            );
          })}
        </div>
      </div>

      <div className="w-px h-6 bg-stone-200 shrink-0" />

      {/* 亮度 */}
      <div className="flex items-center gap-1.5 shrink-0">
        <Sun className="w-3.5 h-3.5 text-stone-400" />
        <input
          type="range"
          min="-50"
          max="50"
          value={brightness}
          onChange={(e) => setBrightness(Number(e.target.value))}
          className="w-20 h-1 accent-brand-500"
        />
        <span className="text-xs text-stone-500 w-8">{brightness > 0 ? `+${brightness}` : brightness}</span>
      </div>

      {/* 对比度 */}
      <div className="flex items-center gap-1.5 shrink-0">
        <Moon className="w-3.5 h-3.5 text-stone-400" />
        <input
          type="range"
          min="-50"
          max="50"
          value={contrast}
          onChange={(e) => setContrast(Number(e.target.value))}
          className="w-20 h-1 accent-brand-500"
        />
        <span className="text-xs text-stone-500 w-8">{contrast > 0 ? `+${contrast}` : contrast}</span>
      </div>

      <div className="w-px h-6 bg-stone-200 shrink-0" />

      {/* 网格显示开关 */}
      <button
        onClick={() => updateSettings({ showGrid: !currentProject.settings.showGrid })}
        className={clsx(
          'flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-medium transition-colors shrink-0',
          currentProject.settings.showGrid
            ? 'bg-brand-50 text-brand-600'
            : 'text-stone-500 hover:bg-stone-100'
        )}
      >
        {currentProject.settings.showGrid ? (
          <Eye className="w-3.5 h-3.5" />
        ) : (
          <EyeOff className="w-3.5 h-3.5" />
        )}
        网格
      </button>

      {/* 大颗粒/小颗粒切换 */}
      <button
        onClick={() =>
          updateSettings({
            beadType: currentProject.settings.beadType === 'large' ? 'small' : 'large',
          })
        }
        className={clsx(
          'flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-medium transition-colors shrink-0',
          currentProject.settings.beadType === 'large'
            ? 'bg-brand-50 text-brand-600'
            : 'text-stone-500 hover:bg-stone-100'
        )}
      >
        {currentProject.settings.beadType === 'large' ? '大颗粒' : '小颗粒'}
      </button>
    </div>
  );
}