import { useRef, useEffect, useCallback, useState } from 'react';
import { useProjectStore } from '@/stores/useProjectStore';
import { useEditorStore } from '@/stores/useEditorStore';
import clsx from 'clsx';

interface GridLayout {
  offsetX: number;
  offsetY: number;
  pixelW: number;
  pixelH: number;
  cellSize: number;
}

export default function CanvasArea() {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const { currentProject, updateGrid, fillGrid, pushUndo, updateSettings, resizeSide } =
    useProjectStore();
  const { activeTool, brushColorIndex, setBrushColor, setBrushColorIndex, setActiveTool } =
    useEditorStore();

  const [isPanning, setIsPanning] = useState(false);
  const [isDrawing, setIsDrawing] = useState(false);
  const [lastGridPos, setLastGridPos] = useState<{ x: number; y: number } | null>(null);
  const panStartRef = useRef({ x: 0, y: 0 });
  const offsetRef = useRef({ x: 0, y: 0 });
  const [hoveredSide, setHoveredSide] = useState<string | null>(null);
  const [draggingSide, setDraggingSide] = useState<string | null>(null);
  const resizeDragRef = useRef<{
    side: 'top' | 'bottom' | 'left' | 'right';
    edgePos: number;
    cellSize: number;
    appliedCells: number;
  } | null>(null);

  // 计算格子大小
  const getCellSize = useCallback(
    (containerW: number, containerH: number) => {
      if (!currentProject) return 0;
      const padding = 40;
      const availW = containerW - padding * 2;
      const availH = containerH - padding * 2;
      const cellByW = Math.floor(availW / currentProject.width);
      const cellByH = Math.floor(availH / currentProject.height);
      return Math.max(2, Math.min(cellByW, cellByH));
    },
    [currentProject]
  );

  // 动态计算网格布局位置（不依赖 state，避免额外重渲染）
  const calcGridLayout = useCallback((): GridLayout | null => {
    const container = containerRef.current;
    if (!container || !currentProject) return null;
    const cw = container.clientWidth;
    const ch = container.clientHeight;
    const cellSize = getCellSize(cw, ch);
    if (cellSize === 0) return null;
    const { zoom, offsetX, offsetY } = currentProject.settings;
    const gridPixelW = currentProject.width * cellSize * zoom;
    const gridPixelH = currentProject.height * cellSize * zoom;
    const gridOffsetX = (cw - gridPixelW) / 2 + offsetX;
    const gridOffsetY = (ch - gridPixelH) / 2 + offsetY;
    return {
      offsetX: gridOffsetX,
      offsetY: gridOffsetY,
      pixelW: gridPixelW,
      pixelH: gridPixelH,
      cellSize: cellSize * zoom,
    };
  }, [currentProject, getCellSize]);

  // 将画布坐标转换为网格坐标
  const getGridPos = useCallback(
    (clientX: number, clientY: number) => {
      const canvas = canvasRef.current;
      const container = containerRef.current;
      if (!canvas || !container || !currentProject) return null;

      const rect = canvas.getBoundingClientRect();
      const gl = calcGridLayout();
      if (!gl) return null;

      const mx = clientX - rect.left;
      const my = clientY - rect.top;

      const gx = Math.floor((mx - gl.offsetX) / gl.cellSize);
      const gy = Math.floor((my - gl.offsetY) / gl.cellSize);

      if (gx < 0 || gx >= currentProject.width || gy < 0 || gy >= currentProject.height) {
        return null;
      }
      return { x: gx, y: gy };
    },
    [currentProject, calcGridLayout]
  );

  // 绘制画布
  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container || !currentProject) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const cw = container.clientWidth;
    const ch = container.clientHeight;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = cw * dpr;
    canvas.height = ch * dpr;
    canvas.style.width = `${cw}px`;
    canvas.style.height = `${ch}px`;
    ctx.scale(dpr, dpr);

    ctx.fillStyle = '#F8F9FA';
    ctx.fillRect(0, 0, cw, ch);

    const cellSize = getCellSize(cw, ch);
    if (cellSize === 0) return;

    const { zoom, offsetX, offsetY, showGrid } = currentProject.settings;
    const gridPixelW = currentProject.width * cellSize * zoom;
    const gridPixelH = currentProject.height * cellSize * zoom;
    const gridOffsetX = (cw - gridPixelW) / 2 + offsetX;
    const gridOffsetY = (ch - gridPixelH) / 2 + offsetY;

    // 绘制网格背景
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(gridOffsetX, gridOffsetY, gridPixelW, gridPixelH);

    // 绘制格子
    const palette = currentProject.palette;
    for (let y = 0; y < currentProject.height; y++) {
      for (let x = 0; x < currentProject.width; x++) {
        const ci = currentProject.gridData[y]?.[x];
        if (ci >= 0 && ci < palette.length) {
          ctx.fillStyle = palette[ci].hex;
          ctx.fillRect(
            gridOffsetX + x * cellSize * zoom,
            gridOffsetY + y * cellSize * zoom,
            cellSize * zoom,
            cellSize * zoom
          );
        }
      }
    }

    // 网格线
    if (showGrid) {
      ctx.strokeStyle = 'rgba(0,0,0,0.06)';
      ctx.lineWidth = 0.5;
      for (let x = 0; x <= currentProject.width; x++) {
        ctx.beginPath();
        ctx.moveTo(gridOffsetX + x * cellSize * zoom, gridOffsetY);
        ctx.lineTo(gridOffsetX + x * cellSize * zoom, gridOffsetY + gridPixelH);
        ctx.stroke();
      }
      for (let y = 0; y <= currentProject.height; y++) {
        ctx.beginPath();
        ctx.moveTo(gridOffsetX, gridOffsetY + y * cellSize * zoom);
        ctx.lineTo(gridOffsetX + gridPixelW, gridOffsetY + y * cellSize * zoom);
        ctx.stroke();
      }
    }

    // 10×10 大格子分区线
    ctx.strokeStyle = 'rgba(0,0,0,0.15)';
    ctx.lineWidth = 1.5;
    const tenStep = 10 * cellSize * zoom;
    for (let x = 0; x <= currentProject.width; x += 10) {
      ctx.beginPath();
      ctx.moveTo(gridOffsetX + x * cellSize * zoom, gridOffsetY);
      ctx.lineTo(gridOffsetX + x * cellSize * zoom, gridOffsetY + gridPixelH);
      ctx.stroke();
    }
    for (let y = 0; y <= currentProject.height; y += 10) {
      ctx.beginPath();
      ctx.moveTo(gridOffsetX, gridOffsetY + y * cellSize * zoom);
      ctx.lineTo(gridOffsetX + gridPixelW, gridOffsetY + y * cellSize * zoom);
      ctx.stroke();
    }

    // 外边框
    ctx.strokeStyle = 'rgba(0,0,0,0.12)';
    ctx.lineWidth = 1;
    ctx.strokeRect(gridOffsetX, gridOffsetY, gridPixelW, gridPixelH);
  }, [currentProject, getCellSize]);

  // 处理绘制操作
  const handleDraw = useCallback(
    (gx: number, gy: number) => {
      if (!currentProject) return;
      if (activeTool === 'brush' && brushColorIndex >= 0) {
        updateGrid(gx, gy, brushColorIndex);
      } else if (activeTool === 'eraser') {
        updateGrid(gx, gy, -1);
      } else if (activeTool === 'fill' && brushColorIndex >= 0) {
        pushUndo();
        fillGrid(gx, gy, brushColorIndex);
        setActiveTool('brush');
      } else if (activeTool === 'eyedropper') {
        const ci = currentProject.gridData[gy]?.[gx];
        if (ci >= 0 && ci < currentProject.palette.length) {
          setBrushColorIndex(ci);
          setBrushColor(currentProject.palette[ci].hex);
          setActiveTool('brush');
        }
      }
    },
    [currentProject, activeTool, brushColorIndex, updateGrid, fillGrid, pushUndo, setBrushColorIndex, setBrushColor, setActiveTool]
  );

  // 鼠标事件
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      if (e.button === 1) {
        // 中键：始终开始平移
        e.preventDefault();
        setIsPanning(true);
        panStartRef.current = { x: e.clientX, y: e.clientY };
        offsetRef.current = {
          x: currentProject?.settings.offsetX ?? 0,
          y: currentProject?.settings.offsetY ?? 0,
        };
        return;
      }

      if (e.button !== 0) return;

      // 左键：先尝试取网格坐标
      const pos = getGridPos(e.clientX, e.clientY);

      if (pos) {
        // 点击在格子内
        if (activeTool === 'fill' || activeTool === 'eyedropper') {
          if (activeTool === 'fill') pushUndo();
          handleDraw(pos.x, pos.y);
          return;
        }
        if (e.shiftKey) {
          pushUndo();
          handleDraw(pos.x, pos.y);
          return;
        }
        // 画笔/橡皮：开始绘制
        pushUndo();
        setIsDrawing(true);
        setLastGridPos(pos);
        handleDraw(pos.x, pos.y);
      } else {
        // 点击在画布外空白区域：开始平移
        setIsPanning(true);
        panStartRef.current = { x: e.clientX, y: e.clientY };
        offsetRef.current = {
          x: currentProject?.settings.offsetX ?? 0,
          y: currentProject?.settings.offsetY ?? 0,
        };
      }
    },
    [activeTool, getGridPos, handleDraw, pushUndo, currentProject]
  );

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      if (isDrawing && (activeTool === 'brush' || activeTool === 'eraser')) {
        const pos = getGridPos(e.clientX, e.clientY);
        if (pos) {
          if (!lastGridPos || pos.x !== lastGridPos.x || pos.y !== lastGridPos.y) {
            setLastGridPos(pos);
            handleDraw(pos.x, pos.y);
          }
        }
        return;
      }

      if (isPanning) {
        const dx = e.clientX - panStartRef.current.x;
        const dy = e.clientY - panStartRef.current.y;
        updateSettings({
          offsetX: offsetRef.current.x + dx,
          offsetY: offsetRef.current.y + dy,
        });
      }
    },
    [isDrawing, isPanning, activeTool, getGridPos, lastGridPos, handleDraw, updateSettings]
  );

  const handleMouseUp = useCallback(() => {
    setIsDrawing(false);
    setIsPanning(false);
    setLastGridPos(null);
  }, []);

  // 滚轮缩放
  const handleWheel = useCallback(
    (e: React.WheelEvent) => {
      e.preventDefault();
      if (!currentProject) return;
      const delta = e.deltaY > 0 ? -0.1 : 0.1;
      const newZoom = Math.max(0.2, Math.min(10, currentProject.settings.zoom + delta));
      updateSettings({ zoom: Math.round(newZoom * 100) / 100 });
    },
    [currentProject, updateSettings]
  );

  // 空格+拖拽平移
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' && !e.repeat) {
        e.preventDefault();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  // ResizeObserver
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const observer = new ResizeObserver(() => draw());
    observer.observe(container);
    return () => observer.disconnect();
  }, [draw]);

  // 数据变化时重绘
  useEffect(() => {
    draw();
  }, [draw, currentProject?.gridData, currentProject?.palette, currentProject?.settings]);

  // ========== 拖拽边框调整大小（实时调整）==========
  const handleResizePointerDown = useCallback(
    (side: 'top' | 'bottom' | 'left' | 'right', e: React.PointerEvent) => {
      e.preventDefault();
      e.stopPropagation();
      const gl = calcGridLayout();
      if (!gl) return;
      const edgePos =
        side === 'top' ? gl.offsetY :
        side === 'bottom' ? gl.offsetY + gl.pixelH :
        side === 'left' ? gl.offsetX :
        gl.offsetX + gl.pixelW;
      resizeDragRef.current = {
        side,
        edgePos,
        cellSize: gl.cellSize,
        appliedCells: 0,
      };
      pushUndo();
      setDraggingSide(side);
    },
    [calcGridLayout, pushUndo]
  );

  // 全局 pointermove / pointerup
  useEffect(() => {
    const handleMove = (e: PointerEvent) => {
      const drag = resizeDragRef.current;
      if (!drag) return;
      const { side, edgePos, cellSize, appliedCells } = drag;

      const pixelDelta =
        side === 'top' ? edgePos - e.clientY :
        side === 'bottom' ? e.clientY - edgePos :
        side === 'left' ? edgePos - e.clientX :
        e.clientX - edgePos;

      // 使用 floor/ceil 确保整格移动（不提前进位），clamp diff 到 ±1 防止跳跃
      const targetCells = pixelDelta >= 0
        ? Math.floor(pixelDelta / cellSize)
        : Math.ceil(pixelDelta / cellSize);
      const diff = targetCells - appliedCells;
      const clampedDiff = Math.max(-1, Math.min(1, diff));
      if (clampedDiff !== 0) {
        drag.appliedCells += clampedDiff;
        resizeSide(side, clampedDiff);
      }
    };

    const handleUp = () => {
      if (resizeDragRef.current) {
        resizeDragRef.current = null;
        setDraggingSide(null);
      }
    };

    if (draggingSide) {
      window.addEventListener('pointermove', handleMove);
      window.addEventListener('pointerup', handleUp);
      return () => {
        window.removeEventListener('pointermove', handleMove);
        window.removeEventListener('pointerup', handleUp);
      };
    }
  }, [draggingSide, resizeSide]);

  // 四边可拖拽边框
  const renderHandles = () => {
    const gl = calcGridLayout();
    if (!gl || !currentProject) return null;
    const { offsetX, offsetY, pixelW, pixelH, cellSize } = gl;
    const handleThick = Math.max(6, Math.min(10, cellSize * 0.3));

    const edges: {
      side: 'top' | 'bottom' | 'left' | 'right';
      style: React.CSSProperties & { cursor: string };
    }[] = [
      {
        side: 'top',
        style: {
          left: offsetX,
          top: offsetY - handleThick / 2,
          width: pixelW,
          height: handleThick,
          cursor: 'ns-resize',
        },
      },
      {
        side: 'bottom',
        style: {
          left: offsetX,
          top: offsetY + pixelH - handleThick / 2,
          width: pixelW,
          height: handleThick,
          cursor: 'ns-resize',
        },
      },
      {
        side: 'left',
        style: {
          left: offsetX - handleThick / 2,
          top: offsetY,
          width: handleThick,
          height: pixelH,
          cursor: 'ew-resize',
        },
      },
      {
        side: 'right',
        style: {
          left: offsetX + pixelW - handleThick / 2,
          top: offsetY,
          width: handleThick,
          height: pixelH,
          cursor: 'ew-resize',
        },
      },
    ];

    return (
      <>
        {/* 四个角的装饰圆点 */}
        {[
          { left: offsetX - 3, top: offsetY - 3 },
          { left: offsetX + pixelW - 3, top: offsetY - 3 },
          { left: offsetX - 3, top: offsetY + pixelH - 3 },
          { left: offsetX + pixelW - 3, top: offsetY + pixelH - 3 },
        ].map((pos, i) => (
          <div
            key={`corner-${i}`}
            className="absolute w-1.5 h-1.5 rounded-full bg-brand-500 z-10 pointer-events-none"
            style={{ left: pos.left, top: pos.top }}
          />
        ))}

        {/* 四边拖拽条 */}
        {edges.map(({ side, style }) => {
          const isHovered = hoveredSide === side;
          const isActive = draggingSide === side;
          const isTopOrBottom = side === 'top' || side === 'bottom';

          return (
            <div
              key={side}
              className={clsx(
                'absolute z-10 select-none',
                isActive ? 'bg-brand-400/40' : isHovered ? 'bg-brand-400/25' : 'bg-transparent',
                'transition-colors duration-150'
              )}
              style={{ ...style, touchAction: 'none' }}
              onMouseEnter={() => setHoveredSide(side)}
              onMouseLeave={() => setHoveredSide(null)}
              onPointerDown={(e) => handleResizePointerDown(side, e)}
            >
              {/* 居中拖拽指示条 */}
              <div
                className={clsx(
                  'absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full',
                  isActive
                    ? 'bg-brand-500'
                    : isHovered
                      ? 'bg-brand-400'
                      : 'bg-brand-300',
                  'transition-colors duration-150'
                )}
                style={{
                  width: isTopOrBottom ? 20 : 4,
                  height: isTopOrBottom ? 4 : 20,
                }}
              />
            </div>
          );
        })}
      </>
    );
  };

  return (
    <div
      ref={containerRef}
      className="flex-1 relative overflow-hidden bg-stone-100"
      onContextMenu={(e) => e.preventDefault()}
    >
      <canvas
        ref={canvasRef}
        className="absolute inset-0 cursor-crosshair"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onWheel={handleWheel}
      />
      {renderHandles()}
    </div>
  );
}